#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: update the running Patch on Cloud Run to the code checked out here (DEPLOY.md step 9, #45).
# Run from anywhere: scripts/update-deploy.sh
# Needs the first deploy done (scripts/deploy-wizard.sh): it reads deploy/cloudrun/wizard.env and env.yaml.
# Build a new image tag, push it, deploy it, check it answers. Settings and secrets stay as they are.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
ENV_FILE="deploy/cloudrun/wizard.env"
LOCAL_ENV="backend/.env"
REGION=us-central1
SERVICE=patch

local_value() {
  [[ -f "$LOCAL_ENV" ]] || return 0
  local line; line=$(grep -E "^${1}=" "$LOCAL_ENV" | tail -n1) || return 0
  printf '%s' "${line#*=}"
}

run() {
  local what="$1"; shift
  printf '\n  %s%s%s\n  %s$ %s%s\n' "$BOLD" "$what" "$RESET" "$DIM" "$*" "$RESET"
  confirm "Run it?" || { note "skipped"; SKIPPED+=("$what"); return 1; }
  while ! "$@"; do
    warn "That failed. Read the message above."
    confirm "Try again?" && continue
    printf '\n  Stopped. Nothing was deployed past this point; the running Patch is unchanged.\n\n'; exit 1
  done
  printf '  %s✓ done%s\n' "$GREEN" "$RESET"
}

[[ -f "$ENV_FILE" && -f deploy/cloudrun/env.yaml ]] || {
  printf 'No first deploy found here (deploy/cloudrun/wizard.env, env.yaml). Run scripts/deploy-wizard.sh first.\n'; exit 1; }
PROJECT_ID=$(_existing PROJECT_ID || true)
PROJECT_NUMBER=$(_existing PROJECT_NUMBER || true)
[[ -n "$PROJECT_ID" && -n "$PROJECT_NUMBER" ]] || { printf 'wizard.env lacks PROJECT_ID or PROJECT_NUMBER.\n'; exit 1; }
IMAGE="$REGION-docker.pkg.dev/$PROJECT_ID/patch/patch"
URL="https://$SERVICE-$PROJECT_NUMBER.$REGION.run.app"

banner "Update Patch on Cloud Run ($PROJECT_ID)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "What will be deployed"
for tool in gcloud docker uv git; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing (gcloud: open the terminal where the first deploy ran)."; exit 1; }
done
git fetch -q origin 2>/dev/null || warn "couldn't reach GitHub; comparing with what was last fetched"
BRANCH=$(git rev-parse --abbrev-ref HEAD)
HEAD_SHORT=$(git log -1 --format='%h %s' | cut -c1-90)
say "Branch $BRANCH, at: $HEAD_SHORT"
LAST=$(_existing DEPLOYED_COMMIT || true)
if [[ -n "$LAST" ]] && git cat-file -e "$LAST" 2>/dev/null; then
  say "Live now: $(git log -1 --format='%h %s' "$LAST" | cut -c1-90)"
  say "New since then: $(git rev-list --count "$LAST"..HEAD) commits."
fi
if [[ -n "$(git status --porcelain --untracked-files=no)" ]]; then
  warn "This checkout has uncommitted changes: they would go into the image."
  confirm "Deploy them anyway?" || exit 1
fi
UPSTREAM=$(git rev-parse --abbrev-ref --symbolic-full-name '@{u}' 2>/dev/null || true)
if [[ -n "$UPSTREAM" ]]; then
  BEHIND=$(git rev-list --count HEAD.."$UPSTREAM")
  if (( BEHIND > 0 )); then
    warn "$UPSTREAM has $BEHIND newer commits than this checkout."
    if confirm "Fast-forward to it first (git merge --ff-only)?"; then
      git merge --ff-only -q "$UPSTREAM" && say "Now at: $(git log -1 --format='%h %s' | cut -c1-90)"
    fi
  fi
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The version"
PREV=$(_existing TAG || true)
NEXT="v1"
if [[ "$PREV" =~ ^v([0-9]+)$ ]]; then NEXT="v$(( BASH_REMATCH[1] + 1 ))"; fi
[[ -n "$PREV" ]] && say "Live now: $PREV."
while true; do
  printf '  %sNew version%s %s[Enter for %s]%s ' "$BOLD" "$RESET" "$DIM" "$NEXT" "$RESET"
  read -r TAG || true
  TAG="${TAG:-$NEXT}"
  [[ "$TAG" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$ ]] && [[ "$TAG" != "$PREV" ]] && break
  warn "A new tag like $NEXT, please (letters, digits, dots, dashes; not the live one)."
done
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The search index"
say "The image carries the search index. It needs rebuilding only when the snapshot or the way it's cut into"
say "chunks changed. Checking against the index from the last build..."
INDEX_STATE=$( (cd backend && uv run --quiet python - <<'PY'
from app.knowledge import load_knowledge
from app.rag.chunking import build_chunks
from app.rag.vector import COLLECTION, _client, fingerprint
try:
    c = _client("data/index-image").get_collection(COLLECTION, embedding_function=None)
except Exception:
    print("missing"); raise SystemExit
meta = c.metadata or {}
same = meta.get("chunks") == fingerprint(build_chunks(load_knowledge()))
print(("same" if same else "changed") + " " + str(meta.get("embedder")))
PY
) 2>/dev/null || echo "missing")
case "$INDEX_STATE" in
  "same "*) printf '  %s✓%s the index is current (%s): no rebuild needed.\n' "$GREEN" "$RESET" "${INDEX_STATE#same }"
            REBUILD=no ;;
  "changed "*) warn "The snapshot or the chunking changed since the index was built: rebuild it."; REBUILD=yes ;;
  *) warn "No index in backend/data/index-image: build it."; REBUILD=yes ;;
esac
[[ "$REBUILD" == no ]] && confirm "Rebuild it anyway?" && REBUILD=yes
if [[ "$REBUILD" == yes ]]; then
  note "With OpenRouter's embedder: a few minutes, well under a cent."
  key=$(local_value OPENROUTER_API_KEY)
  if [[ -z "$key" ]] || ! confirm "Use the OpenRouter key from backend/.env for the build?"; then
    ask_secret key "OpenRouter key for the build (hidden):"
  fi
  rm -rf backend/data/index-image
  (cd backend && OPENROUTER_API_KEY="$key" EMBEDDER=openrouter EMBED_MODEL= INDEX_PATH=data/index-image \
     uv run python -m app.rag.build_index) || { key=""; warn "The index build failed: see above."; exit 1; }
  key=""
  printf '  %s✓ index built%s\n' "$GREEN" "$RESET"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Build and upload $TAG"
note "A few minutes; the upload sends only the layers that changed."
run "Build the image" docker build --build-arg EMBEDDER=openrouter -t "$IMAGE:$TAG" . || exit 1
grep -q "$REGION-docker.pkg.dev" "$HOME/.docker/config.json" 2>/dev/null \
  || gcloud auth configure-docker "$REGION-docker.pkg.dev" --quiet >/dev/null
run "Upload it" docker push "$IMAGE:$TAG" || exit 1
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Deploy $TAG"
say "Cloud Run starts $TAG next to the running version and switches over once it answers: no downtime."
note "Settings from deploy/cloudrun/env.yaml again; the secrets stay as they are."
run "Deploy" gcloud run deploy "$SERVICE" --image="$IMAGE:$TAG" --region="$REGION" --project="$PROJECT_ID" \
  --env-vars-file=deploy/cloudrun/env.yaml || exit 1
say "Checking that $URL answers..."
if curl -fsS --max-time 90 -o /dev/null "$URL/api/health"; then
  printf '  %s✓%s %s answers, running %s\n' "$GREEN" "$RESET" "$URL" "$TAG"
  write_env TAG "$TAG"
  write_env DEPLOYED_COMMIT "$(git rev-parse HEAD)"
else
  warn "$URL/api/health didn't answer. The log says why:"
  note "  gcloud logging read 'resource.type=\"cloud_run_revision\" AND resource.labels.service_name=\"patch\"' --limit=50 --freshness=1h"
  say "To go back: gcloud run services update-traffic $SERVICE --region=$REGION --to-revisions=<previous>=100"
  note "  (gcloud run revisions list --service=$SERVICE --region=$REGION shows them)"
  exit 1
fi
if [[ -n "$PREV" ]] && confirm "Delete the old image $PREV, to keep storage free? (you can't roll back to it afterwards)"; then
  gcloud artifacts docker images delete "$IMAGE:$PREV" --quiet --delete-tags >/dev/null 2>&1 \
    && printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$PREV" || warn "couldn't delete $PREV; it can stay"
fi
say "Open $URL and look around: a reload shows the new version."
pause "Press Enter to finish"

finish
